// Enumerate four-edge removals once, using a packed exact degree histogram (base 32). Complete only by adding an originally blue edge.
use std::{collections::HashMap,io::{self,BufRead}};
type A=[u32;26];fn unit(d:u32)->u64{1u64<<(5*d)}fn sig(g:&A)->Vec<(u32,u64)>{let mut out=vec![];for &v in g{let mut s=v;let mut h=0;while s!=0{let j=s.trailing_zeros()as usize;s&=s-1;h+=unit(g[j].count_ones())}out.push((v.count_ones(),h))}out.sort_unstable();out}
struct Job{old:A,g:A,edges:Vec<(usize,usize)>,pre:HashMap<u64,Vec<(u32,u32)>>,target:Vec<(u32,u64)>,ct:[u64;5],hits:Vec<A>}
impl Job{fn run(&mut self,start:usize,k:usize,h:u64){if k==0{self.ct[0]+=1;if let Some(pairs)=self.pre.get(&h){self.ct[1]+=1;for &(x,y) in pairs{for i in 0..26{if self.g[i].count_ones()!=x{continue}for j in 0..26{if i==j||(x==y&&j<i)||self.g[j].count_ones()!=y||self.old[i]>>j&1!=0{continue}self.ct[2]+=1;if self.g[i]&self.g[j]!=0{continue}self.ct[3]+=1;self.g[i]^=1<<j;self.g[j]^=1<<i;if sig(&self.g)==self.target{self.ct[4]+=1;self.hits.push(self.g)}self.g[i]^=1<<j;self.g[j]^=1<<i;}}}}return}for t in start..=self.edges.len()-k{let(i,j)=self.edges[t];let(d,e)=(self.g[i].count_ones(),self.g[j].count_ones());self.g[i]^=1<<j;self.g[j]^=1<<i;self.run(t+1,k-1,h-unit(d)-unit(e)+unit(d-1)+unit(e-1));self.g[i]^=1<<j;self.g[j]^=1<<i;}}}
fn main(){for line in io::stdin().lock().lines(){let vals:Vec<u32>=line.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let old:A=vals[..26].try_into().unwrap();let target:A=vals[26..].try_into().unwrap();let mut pre=HashMap::new();let h=target.iter().map(|v|unit(v.count_ones())).sum::<u64>();for x in [4,6,7]{for y in [4,6,7]{if x<=y{pre.entry(h-unit(x)-unit(y)+unit(x-1)+unit(y-1)).or_insert_with(Vec::new).push((x-1,y-1));}}}let mut edges=vec![];for i in 0..26{for j in 0..i{if old[i]>>j&1!=0{edges.push((i,j))}}}assert_eq!(edges.len(),79);let mut a=Job{old,g:old,edges,pre,target:sig(&target),ct:[0;5],hits:vec![]};a.run(0,4,old.iter().map(|v|unit(v.count_ones())).sum());println!("{:?}|{:?}",a.ct,a.hits)}}
